class Solution { static constexpr int MOD=1000000007;vector<int> nums;vector<vector<int>> memo;int full;int dfs(int mask,int last){if(mask==full)return 1;if(memo[mask][last]!=-1)return memo[mask][last];long long ways=0;for(int next=0;next<(int)nums.size();++next)if(!(mask&(1<<next))&&(nums[last]%nums[next]==0||nums[next]%nums[last]==0))ways=(ways+dfs(mask|1<<next,next))%MOD;return memo[mask][last]=ways;}public:int specialPerm(vector<int>& input){nums=input;full=(1<<nums.size())-1;memo.assign(1<<nums.size(),vector<int>(nums.size(),-1));long long answer=0;for(int start=0;start<(int)nums.size();++start)answer=(answer+dfs(1<<start,start))%MOD;return answer;} };
